import axios from 'axios';
import StatsBar from './components/StatsBar';
import ArticleCard from './components/ArticleCard';

const API = 'http://localhost:5000/api';

// ── Skeleton loader ──────────────────────────────────────────────────────────
function ArticleSkeleton() {
  return (
    <div style={{
      background: '#12121a', border: '1px solid #2a2a3a',
      borderRadius: 12, overflow: 'hidden'
    }}>
      <div className="skeleton" style={{ height: 160 }} />
      <div style={{ padding: '18px 20px', display: 'flex', flexDirection: 'column', gap: 12 }}>
        <div className="skeleton" style={{ height: 12, width: '40%' }} />
        <div className="skeleton" style={{ height: 18, width: '90%' }} />
        <div className="skeleton" style={{ height: 18, width: '70%' }} />
        <div className="skeleton" style={{ height: 60 }} />
      </div>
    </div>
  );
}

// ── Filter pill ──────────────────────────────────────────────────────────────
function Pill({ label, active, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        padding: '6px 16px',
        borderRadius: 99,
        border: `1px solid ${active ? '#f5c842' : '#2a2a3a'}`,
        background: active ? '#f5c84220' : 'transparent',
        color: active ? '#f5c842' : '#9090b0',
        fontSize: 13, fontWeight: 500,
        transition: 'all 0.15s',
        whiteSpace: 'nowrap',
      }}
    >
      {label}
    </button>
  );
}

// ── Toast notification ────────────────────────────────────────────────────────
function Toast({ message, type, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 3500);
    return () => clearTimeout(t);
  }, [onDone]);

  const bg = type === 'success' ? '#3ecf8e' : type === 'error' ? '#f06060' : '#f5c842';
  return (
    <div style={{
      position: 'fixed', bottom: 28, right: 28, zIndex: 999,
      background: bg, color: '#0a0a0f',
      padding: '12px 22px', borderRadius: 10,
      fontWeight: 600, fontSize: 14,
      boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
      animation: 'fadeIn 0.3s ease',
    }}>
      {message}
    </div>
  );
}

// ── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [articles,   setArticles]   = useState([]);
  const [stats,      setStats]      = useState(null);
  const [categories, setCategories] = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [statsLoad,  setStatsLoad]  = useState(true);
  const [fetching,   setFetching]   = useState(false);
  const [toast,      setToast]      = useState(null);

  // Filters
  const [search,    setSearch]    = useState('');
  const [liveSearch,setLiveSearch]= useState('');
  const [sentiment, setSentiment] = useState('');
  const [category,  setCategory]  = useState('');
  const [page,      setPage]      = useState(1);

  // ── Data loaders ────────────────────────────────────────────────────────────
  const loadArticles = useCallback(async (overrides = {}) => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/articles`, {
        params: {
          search:    overrides.search    ?? search,
          sentiment: overrides.sentiment ?? sentiment,
          category:  overrides.category  ?? category,
          page:      overrides.page      ?? page,
        }
      });
      setArticles(res.data.articles || []);
    } catch {
      showToast('Failed to load articles', 'error');
    }
    setLoading(false);
  }, [search, sentiment, category, page]);

  const loadStats = useCallback(async () => {
    setStatsLoad(true);
    try {
      const res = await axios.get(`${API}/stats`);
      setStats(res.data);
    } catch { /* silent */ }
    setStatsLoad(false);
  }, []);

  const loadCategories = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/categories`);
      setCategories(res.data.categories || []);
    } catch { /* silent */ }
  }, []);

  useEffect(() => {
    loadArticles();
    loadStats();
    loadCategories();
  }, [sentiment, category, page]); // re-load when filters change

  // Live search debounce
  useEffect(() => {
    const t = setTimeout(() => {
      setPage(1);
      loadArticles({ search: liveSearch, page: 1 });
    }, 400);
    return () => clearTimeout(t);
  }, [liveSearch]);

  // ── Helpers ─────────────────────────────────────────────────────────────────
  const showToast = (message, type = 'info') => setToast({ message, type });

  const handlePipelineRun = async (cat = 'technology') => {
    setFetching(true);
    showToast(`⚡ Fetching ${cat} news…`, 'info');
    try {
      const res = await axios.post(`${API}/run-pipeline`, { category: cat });
      showToast(`✅ Added ${res.data.new_articles} new articles!`, 'success');
      await loadArticles();
      await loadStats();
      await loadCategories();
    } catch {
      showToast('Pipeline failed — check backend logs', 'error');
    }
    setFetching(false);
  };

  const applyFilter = (key, value) => {
    const reset = { sentiment, category, page: 1, [key]: value };
    if (key === 'sentiment') setSentiment(value);
    if (key === 'category')  setCategory(value);
    setPage(1);
    loadArticles(reset);
  };

  const clearFilters = () => {
    setSentiment(''); setCategory(''); setSearch(''); setLiveSearch(''); setPage(1);
    loadArticles({ search: '', sentiment: '', category: '', page: 1 });
  };

  const hasFilters = sentiment || category || liveSearch;

  // ── Render ──────────────────────────────────────────────────────────────────
  return (
    <div style={{ minHeight: '100vh', background: '#0a0a0f' }}>

      {/* ─── Header ─────────────────────────────────────────────────── */}
      <header style={{
        borderBottom: '1px solid #2a2a3a',
        padding: '0 32px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        height: 64,
        position: 'sticky', top: 0, zIndex: 100,
        background: '#0a0a0fdd',
        backdropFilter: 'blur(12px)',
      }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 10 }}>
          <h1 style={{
            fontFamily: 'Playfair Display, serif',
            fontSize: 22, fontWeight: 900, color: '#f5c842',
            letterSpacing: -0.5
          }}>
            NewsIQ
          </h1>
          <span style={{ fontSize: 12, color: '#5a5a7a', letterSpacing: 2, textTransform: 'uppercase' }}>
            Intelligence Platform
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          {/* Pipeline trigger dropdown-style */}
          <div style={{ position: 'relative' }}>
            <select
              disabled={fetching}
              onChange={e => { if (e.target.value) { handlePipelineRun(e.target.value); e.target.value = ''; } }}
              style={{
                padding: '8px 16px',
                background: fetching ? '#2a2a3a' : '#f5c84220',
                color: fetching ? '#5a5a7a' : '#f5c842',
                border: '1px solid ' + (fetching ? '#2a2a3a' : '#f5c84250'),
                borderRadius: 8, fontSize: 13, fontWeight: 600,
                cursor: fetching ? 'not-allowed' : 'pointer',
              }}
            >
              <option value="">{fetching ? 'Fetching…' : '⚡ Fetch News'}</option>
              {['technology', 'science', 'business', 'health', 'entertainment', 'sports'].map(c => (
                <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>
              ))}
            </select>
          </div>
        </div>
      </header>

      {/* ─── Main ───────────────────────────────────────────────────── */}
      <main style={{ maxWidth: 1280, margin: '0 auto', padding: '32px 24px' }}>

        {/* Page title */}
        <div style={{ marginBottom: 28 }}>
          <h2 style={{
            fontFamily: 'Playfair Display, serif',
            fontSize: 36, fontWeight: 900, color: '#f0f0f8',
            lineHeight: 1.1, marginBottom: 6
          }}>
            Today's Intelligence
          </h2>
          <p style={{ color: '#5a5a7a', fontSize: 14 }}>
            AI-powered summaries, sentiment analysis & key insights — in real time
          </p>
        </div>

        {/* Stats */}
        <StatsBar stats={stats} loading={statsLoad} />

        {/* ─── Search & Filters ─────────────────────────────────────── */}
        <div style={{
          display: 'flex', flexWrap: 'wrap', gap: 12,
          marginBottom: 28, alignItems: 'center'
        }}>
          {/* Search box */}
          <div style={{ position: 'relative', flex: '1 1 260px' }}>
            <span style={{
              position: 'absolute', left: 14, top: '50%', transform: 'translateY(-50%)',
              color: '#5a5a7a', fontSize: 16, pointerEvents: 'none'
            }}>🔍</span>
            <input
              value={liveSearch}
              onChange={e => setLiveSearch(e.target.value)}
              placeholder="Search headlines, topics…"
              style={{
                width: '100%', padding: '10px 16px 10px 40px',
                background: '#12121a', border: '1px solid #2a2a3a',
                borderRadius: 10, color: '#f0f0f8', fontSize: 14,
                outline: 'none', transition: 'border-color 0.2s',
              }}
              onFocus={e => e.target.style.borderColor = '#f5c84260'}
              onBlur={e  => e.target.style.borderColor = '#2a2a3a'}
            />
          </div>

          {/* Sentiment pills */}
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {['', 'positive', 'negative', 'neutral'].map(s => (
              <Pill
                key={s || 'all'}
                label={s ? s.charAt(0).toUpperCase() + s.slice(1) : 'All Moods'}
                active={sentiment === s}
                onClick={() => applyFilter('sentiment', s)}
              />
            ))}
          </div>
        </div>

        {/* Category filter row */}
        {categories.length > 0 && (
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 24 }}>
            <Pill label="All Topics" active={!category} onClick={() => applyFilter('category', '')} />
            {categories.map(c => (
              <Pill
                key={c}
                label={c.charAt(0).toUpperCase() + c.slice(1)}
                active={category === c}
                onClick={() => applyFilter('category', c)}
              />
            ))}
          </div>
        )}

        {/* Active filter notice */}
        {hasFilters && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
            <span style={{ fontSize: 13, color: '#9090b0' }}>Filters active</span>
            <button
              onClick={clearFilters}
              style={{
                background: 'none', border: '1px solid #2a2a3a', borderRadius: 6,
                padding: '3px 12px', color: '#f06060', fontSize: 12,
              }}
            >
              ✕ Clear all
            </button>
          </div>
        )}

        {/* ─── Article Grid ──────────────────────────────────────────── */}
        {loading ? (
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))',
            gap: 20
          }}>
            {[...Array(6)].map((_, i) => <ArticleSkeleton key={i} />)}
          </div>
        ) : articles.length === 0 ? (
          <div style={{
            textAlign: 'center', padding: '80px 20px',
            color: '#5a5a7a'
          }}>
            <div style={{ fontSize: 48, marginBottom: 16 }}>📭</div>
            <div style={{ fontSize: 18, color: '#9090b0', marginBottom: 8 }}>No articles found</div>
            <p style={{ fontSize: 14 }}>
              {stats?.total === 0
                ? 'Use the "⚡ Fetch News" button above to get started!'
                : 'Try different search terms or clear your filters.'}
            </p>
          </div>
        ) : (
          <>
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))',
              gap: 20
            }}>
              {articles.map((a, i) => <ArticleCard key={a.id} article={a} index={i} />)}
            </div>

            {/* Pagination */}
            <div style={{
              display: 'flex', justifyContent: 'center', gap: 12,
              marginTop: 40, alignItems: 'center'
            }}>
              <button
                disabled={page <= 1}
                onClick={() => { setPage(p => p - 1); loadArticles({ page: page - 1 }); }}
                style={{
                  padding: '8px 20px', borderRadius: 8,
                  background: page <= 1 ? '#12121a' : '#f5c84220',
                  color: page <= 1 ? '#3a3a5a' : '#f5c842',
                  border: `1px solid ${page <= 1 ? '#2a2a3a' : '#f5c84250'}`,
                  fontWeight: 600, fontSize: 13,
                }}
              >
                ← Prev
              </button>
              <span style={{ color: '#5a5a7a', fontSize: 13 }}>Page {page}</span>
              <button
                disabled={articles.length < 12}
                onClick={() => { setPage(p => p + 1); loadArticles({ page: page + 1 }); }}
                style={{
                  padding: '8px 20px', borderRadius: 8,
                  background: articles.length < 12 ? '#12121a' : '#f5c84220',
                  color: articles.length < 12 ? '#3a3a5a' : '#f5c842',
                  border: `1px solid ${articles.length < 12 ? '#2a2a3a' : '#f5c84250'}`,
                  fontWeight: 600, fontSize: 13,
                }}
              >
                Next →
              </button>
            </div>
          </>
        )}
      </main>

      {/* Footer */}
      <footer style={{
        textAlign: 'center', padding: '32px 24px',
        borderTop: '1px solid #2a2a3a',
        color: '#3a3a5a', fontSize: 12, marginTop: 60
      }}>
        NewsIQ · Powered by Gemini AI · NewsData.io · Supabase
      </footer>

      {/* Toast */}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onDone={() => setToast(null)}
        />
      )}
    </div>
  );
}
